// 查询参数解析 + 白名单校验：防 SQL 注入、防越权字段、防非法分页
const SORTABLE = new Set(['id', 'createdAt', 'score', 'title']);
const FILTERABLE = { status: 'string', tag: 'string', score: 'integer', id: 'integer' };
const MAX_LIMIT = 100;

function parseQuery(raw) {
  const sp = new URLSearchParams(raw);
  const errors = [];
  const out = { sort: null, filters: {}, limit: 20, offset: 0, orderSql: null };

  const sortRaw = sp.get('sort');
  if (sortRaw !== null) {
    const m = /^(-?)([A-Za-z][A-Za-z0-9]{0,20})$/.exec(sortRaw);
    if (!m) {
      errors.push('sort: malformed token: ' + JSON.stringify(sortRaw));
    } else {
      const sign = m[1];
      const field = m[2];
      if (!SORTABLE.has(field)) {
        errors.push('sort: field not in whitelist: ' + field);
      } else {
        // 白名单命中后才拼 SQL 标识符；字段名本身来自白名单，不是用户串
        out.sort = { field, dir: sign === '-' ? 'desc' : 'asc' };
        out.orderSql = '"' + field + '" ' + (sign === '-' ? 'DESC' : 'ASC');
      }
    }
  }

  for (const [k, kind] of Object.entries(FILTERABLE)) {
    const v = sp.get(k);
    if (v === null) continue;
    if (kind === 'integer') {
      if (!/^-?\d{1,9}$/.test(v)) { errors.push('filter ' + k + ': not an integer'); continue; }
      out.filters[k] = Number(v);
    } else {
      if (!/^[A-Za-z0-9_-]{1,40}$/.test(v)) { errors.push('filter ' + k + ': illegal characters'); continue; }
      out.filters[k] = v;
    }
  }

  const limit = sp.get('limit');
  if (limit !== null) {
    if (!/^\d{1,9}$/.test(limit)) errors.push('limit: must be a non-negative integer');
    else if (Number(limit) < 1) errors.push('limit: must be >= 1');
    else out.limit = Math.min(Number(limit), MAX_LIMIT);   // 越界值夹到上限而不是报错
  }
  const offset = sp.get('offset');
  if (offset !== null) {
    if (!/^\d{1,6}$/.test(offset)) errors.push('offset: must be a non-negative integer');
    else out.offset = Number(offset);
  }

  return { ok: errors.length === 0, errors, query: out };
}

const cases = [
  ['sort=-score&status=published&limit=25&offset=50', true],
  ['sort=createdAt&score=90&tag=db', true],
  ['sort=id%3B%20DROP%20TABLE%20articles', false],
  ['sort=password', false],
  ['sort=id%20--', false],
  ['score=abc', false],
  ['tag=%3Cscript%3E', false],
  ['limit=99999', true],
  ['limit=0', false],
  ['limit=abc', false],
  ['offset=-1', false],
];

for (const pair of cases) {
  const raw = pair[0];
  const expectOk = pair[1];
  const r = parseQuery(raw);
  console.log('input=' + raw);
  console.log('  expect_ok=' + expectOk + ' actual_ok=' + r.ok + ' match=' + (expectOk === r.ok));
  console.log('  errors=' + JSON.stringify(r.errors));
  console.log('  orderSql=' + (r.query.orderSql === null ? 'null' : JSON.stringify(r.query.orderSql))
    + ' filters=' + JSON.stringify(r.query.filters)
    + ' limit=' + r.query.limit + ' offset=' + r.query.offset);
}
